// Regenerates AUTOGENERATED `paths:` blocks in `.github/workflows/*.yml` from
// the @trezor/* publish dependency graph.
//
// Each generated block is delimited by sentinel markers:
//
//   # >>> AUTOGENERATED:<SENTINEL_NAME> — yarn gen:workflow-paths
//   - "packages/<pkg>/**"
//   ...
//   # <<< AUTOGENERATED:<SENTINEL_NAME>
//
// The set of sentinel names, their root packages and the workflow files each
// block must live in is configured in `SENTINEL_CONFIGS` below. The generator
// walks every workflow file, replaces each sentinel's body with
// `computePublishClosure(roots)`, and exits non-zero (in both modes) if any
// configured block is missing — deleting a block drops all of its filters at
// once, so it must not pass silently.
//
// In `--check` mode the generator does not write — it exits non-zero if any
// file is out of sync. Wire this into the lint job so drift fails the PR.
//
// Non-package signals (submodules, dockerfiles, build scripts) cannot be
// derived from the dep graph and live in a sibling "Manual additions" block.

import fs from 'node:fs';
import { createRequire } from 'node:module';
import path from 'node:path';

// `@trezor/requirements` is CJS: Node cannot detect its named exports from ESM,
// hence `createRequire` plus the type-only import below.
import type * as Requirements from '@trezor/requirements';

import { CONNECT_PUBLISH_ROOTS } from './connect-publish-roots';

const { computePublishClosure, createReadWorkspaceDeps, getWorkspaceDirectoryMap } = createRequire(
    import.meta.url,
)('@trezor/requirements') as typeof Requirements;

const ROOT = path.resolve(import.meta.dirname, '..', '..');
const WORKFLOWS_DIR = path.join(ROOT, '.github', 'workflows');
const readWorkspaceDeps = createReadWorkspaceDeps(ROOT);
const workspaceDirs = getWorkspaceDirectoryMap(ROOT);

const SENTINEL_CONFIGS: Record<string, { roots: string[]; files: string[] }> = {
    CONNECT_PUBLISH_DEPS: {
        roots: CONNECT_PUBLISH_ROOTS,
        files: ['test-connect.yml', 'test-connect-misc.yml'],
    },
};

const SENTINEL_START_RE = /^(?<indent>\s*)# >>> AUTOGENERATED:(?<name>[A-Z0-9_]+)\b.*$/;

// Resolves each closure entry to its actual workspace location so that
// @trezor/* packages outside `packages/` (e.g. `suite/e2e`) get the right
// glob if they ever land in a closure.
const resolveRelativeLocation = (pkg: string): string => {
    const dir = workspaceDirs.get(`@trezor/${pkg}`);
    if (dir === undefined) {
        throw new Error(
            `Closure references @trezor/${pkg} but no such workspace exists. Did the package move or get renamed?`,
        );
    }

    return path.relative(ROOT, dir).replaceAll('\\', '/');
};

const formatPathLines = (closure: Set<string>, indent: string): string[] =>
    [...closure]
        .map(resolveRelativeLocation)
        .sort()
        .map(location => `${indent}- "${location}/**"`);

const regenerate = (content: string, filePath: string, seenSentinels: Set<string>): string => {
    const result: string[] = [];

    // While set, we're inside an AUTOGENERATED block: the old body is dropped
    // (the fresh one was already emitted at the start marker) until we hit the
    // matching end marker, which we re-emit and then clear the state.
    let pendingEndMarker: string | null = null;

    for (const line of content.split('\n')) {
        if (pendingEndMarker !== null) {
            if (line === pendingEndMarker) {
                result.push(line);
                pendingEndMarker = null;
            }
            continue;
        }

        const startMatch = line.match(SENTINEL_START_RE);
        if (!startMatch) {
            result.push(line);
            continue;
        }

        const indent = startMatch.groups?.indent ?? '';
        const name = startMatch.groups?.name;
        const config = name === undefined ? undefined : SENTINEL_CONFIGS[name];

        if (!config) {
            throw new Error(
                `Unknown sentinel "${name}" in ${filePath}. Add it to SENTINEL_CONFIGS in scripts/ci/gen-workflow-paths.ts.`,
            );
        }

        seenSentinels.add(`${path.basename(filePath)}:${name}`);

        const closure = computePublishClosure(config.roots, readWorkspaceDeps);

        result.push(line);
        result.push(...formatPathLines(closure, indent));
        pendingEndMarker = `${indent}# <<< AUTOGENERATED:${name}`;
    }

    if (pendingEndMarker !== null) {
        throw new Error(
            `Sentinel block in ${filePath} has no matching end marker (expected "${pendingEndMarker}").`,
        );
    }

    return result.join('\n');
};

const findWorkflowFiles = (): string[] =>
    fs
        .readdirSync(WORKFLOWS_DIR)
        .filter(name => name.endsWith('.yml') || name.endsWith('.yaml'))
        .map(name => path.join(WORKFLOWS_DIR, name));

const main = () => {
    const checkMode = process.argv.includes('--check');
    const driftedFiles: string[] = [];
    const seenSentinels = new Set<string>();

    for (const filePath of findWorkflowFiles()) {
        const content = fs.readFileSync(filePath, 'utf-8');
        if (!content.includes('# >>> AUTOGENERATED:')) {
            continue;
        }

        const updated = regenerate(content, filePath, seenSentinels);
        if (updated === content) {
            continue;
        }

        if (checkMode) {
            driftedFiles.push(path.relative(ROOT, filePath));
        } else {
            fs.writeFileSync(filePath, updated);
            console.log(`updated ${path.relative(ROOT, filePath)}`);
        }
    }

    // A removed block is otherwise indistinguishable from a workflow that never
    // had one, so the drift check above would pass while every filter in the
    // block is gone. Asserted in both modes: regenerating must not look like it
    // fixed a workflow whose block was deleted.
    const missing = Object.entries(SENTINEL_CONFIGS).flatMap(([name, { files }]) =>
        files
            .filter(file => !seenSentinels.has(`${file}:${name}`))
            .map(file => `${file} (${name})`),
    );

    if (missing.length > 0) {
        console.error('Expected AUTOGENERATED blocks are missing:');
        for (const entry of missing) {
            console.error(`  - ${entry}`);
        }
        console.error(
            '\nRestore the block or update SENTINEL_CONFIGS in scripts/ci/gen-workflow-paths.ts.',
        );
        process.exit(1);
    }

    if (checkMode && driftedFiles.length > 0) {
        console.error('Workflow path filters are out of date:');
        for (const file of driftedFiles) {
            console.error(`  - ${file}`);
        }
        console.error("\nRun 'yarn gen:workflow-paths' and commit the changes.");
        process.exit(1);
    }
};

main();
